    """Repeat the stencil panel across the lattice, recoloring by row label."""
    h, w = len(grid), len(grid[0])
    full_rows = {}
    for r, row in enumerate(grid):
        if row and row[0] != 0 and all(v == row[0] for v in row):
            full_rows.setdefault(row[0], []).append(r)
    full_cols = {}
    for c in range(w):
        v = grid[0][c]
        if v != 0 and all(grid[r][c] == v for r in range(h)):
            full_cols.setdefault(v, []).append(c)
    shared = [v for v in full_rows if v in full_cols]
    if not shared:
        raise ValueError("Could not identify the lattice divider color")
    divider = max(shared, key=lambda v: len(full_rows[v]) + len(full_cols[v]))
    row_cuts = [-1] + full_rows[divider] + [h]
    col_cuts = [-1] + full_cols[divider] + [w]
    row_spans = [(row_cuts[i] + 1, row_cuts[i + 1]) for i in range(len(row_cuts) - 1)]
    col_spans = [(col_cuts[i] + 1, col_cuts[i + 1]) for i in range(len(col_cuts) - 1)]

    # The first panel of each panel-row carries that row's output color.
    labels = []
    for r0, r1 in row_spans:
        colors = {grid[r][c] for r in range(r0, r1) for c in range(*col_spans[0])
                  if grid[r][c] != 0}
        if len(colors) != 1:
            raise ValueError("Expected one row-label color in the first panel")
        labels.append(next(iter(colors)))

    # The non-label panel with the most occupied cells is the stencil.
    candidates = []
    for pi, (r0, r1) in enumerate(row_spans):
        for pj, (c0, c1) in enumerate(col_spans[1:], start=1):
            cells = [(r - r0, c - c0) for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] != 0]
            if cells:
                candidates.append((len(cells), cells))
    if not candidates:
        raise ValueError("No stencil panel found")
    stencil = max(candidates, key=lambda item: item[0])[1]

    out = [row[:] for row in grid]
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = 0
            color = labels[row_spans.index((r0, r1))]
            for dr, dc in stencil:
                out[r0 + dr][c0 + dc] = color
    return out
